"""Complete existing coordinates and attach narrowly verified film provenance."""
from copy import deepcopy
from best_guess_helpers import current_data,change,write_revision,dated_source,DATE
from research_helpers import assessment
D=current_data();changes=[]
new_sources=[
 dated_source('src-pandorum-rotating-maintenance','Pandorum: original transport design','Wikipedia contributors','https://en.wikipedia.org/wiki/Pandorum','Plot opening: passengers sleep while rotating crew wake every two years to maintain Elysium; later Gallo destroys the order.','Bounded plot passage, not a full film viewing or a canonical mission entitlement charter.'),
 dated_source('src-equals-continuing-human-work','Equals: Collective and occupations','Wikipedia contributors','https://en.wikipedia.org/wiki/Equals_(film)','Plot opening: Collective legislative control; Silas works as an illustrator and later seeks gardening work.','Social rules and occupations are supported; household provision and automation capacity remain editorial inference.'),
]
for s in new_sources:changes.append(change(D,'sources',s))
for rid,sid in [('pandorum-awake-crew-zero','src-pandorum-rotating-maintenance'),('equals-collective-assigned-zero','src-equals-continuing-human-work')]:
 r=deepcopy(D['societies'][rid]);r['source_ids'].append(sid)
 for a in r['axis_assessment'].values():a['source_ids'].append(sid)
 for e in r['evidence']:e['source_ids'].append(sid)
 r['review']['method']+='; bounded plot passage verifies recurring crew duties or continuing human occupations'
 changes.append(change(D,'societies',r))

# A source's silence and an economic interpretation are not themselves canon facts.
r=deepcopy(D['societies']['her-before-departure'])
r['canon_facts']=['Theodore writes letters for clients.','OS ONE is marketed as artificial consciousness for consumers.']
r['uncertainties']=[x for x in r['uncertainties'] if x!='The released film and later screenplay scenes need a fuller pass.']
r['review']['method']+='; canon-fact list narrowed to actual depicted work and consumer premise'
changes.append(change(D,'societies',r))

rows=[
('lustrous-lunarian-sustainable-city',{'nonworking':(.4,[.1,.8],'Active Lunarian all-age person scenario under survival-independent provision counts retained jobs for purpose, restaurant service, research, care and military activity; schedules do not count people.')},
'''Lunarians are active human descendants and an explicit person proxy, with leadership concentrated around Aechmea. Retained jobs for purpose and mental health overlap with the zero-variant theme without creating a second copy of the same economy. The intermediate nonworking best guess counts restaurant service, research, care and military activity even when nobody must earn necessities. A typical schedule does not establish how many people have ongoing roles, so the interval remains wide. The strong floor concerns the maintained city rather than every excluded being. The unofficial translation and absence of a detailed entitlement charter remain source limitations, not reasons to leave a coordinate empty.''',
['The companion city account describes synthetic materials, recycling and survival without jobs.','Government retains work for purpose and mental health while useful occupations continue.']),
('doraemon-chamocha-before-revolt',{'control':(-.25,[-.9,.45],'Initial human commands coexist with independent robot invention and growing practical dependence. Central scenario gives machines substantial effective autonomy without importing their later coup as already complete.')},
'''The control best guess recognizes both initial human service commands and the robot inventor’s independent creation of further technology. Its negative but intermediate point gives growing machine autonomy substantial weight without claiming the later overthrow is already complete. A wide interval allows stronger human authority or deeper dependence than the backstory specifies. The existing high nonworking estimate follows the explicit delegation of nearly every kind of work while retaining useful exceptions such as scientific research. It is not a census. The coup changes material security, and the final pledge to rely less on robots does not establish another implemented economy with measured guarantees or participation.''',
['Chamocha delegates agriculture, industry, shops, medicine, administration and invention to robots.','Humans initially command services, but an independently inventive robot later overthrows them.']),
('fallout-watoga-prewar-exclusion',{'nonworking':(.6,[.25,.9],'Prewar all-age human city scenario allows extensive displacement and privileged robot-supported leisure while counting care, administration and useful informal work; unemployment and outmigration do not determine participation.')},
'''Corporate authorities and privileged residents direct admission and service policy, keeping productive control near concentrated human authority. The high nonworking best guess allows substantial displacement and robot-supported leisure while counting administration, care and useful informal work. Unemployment alone is not nonparticipation, and people leaving the city do not remain in its denominator. The broad interval concerns the prewar living city community rather than hostile patrols after sabotage or nuclear catastrophe. Weak guarantees follow costly admission and restricted services even when rich residents are comfortable. Municipal automation also does not prove that every commodity is locally produced or available free of charge.''',
['Watoga automates municipal services while replacement drives unemployment and outmigration.','Property wealth and corporate approval restrict residence and services.']),
('fallout-vault112-active-captives',{'nonworking':(.6,[.15,.95],'Active living captive scenario permits much simulated leisure but counts useful virtual care, creation or organizing; fictional neighbors, temporary visitors and dead captives are excluded.')},
'''Human overseer Stanislaus Braun controls the system, rather than its Robobrain maintainers or the residents collectively. Strong bodily support and severe coercion therefore coexist without becoming an AI welfare order. The high nonworking best guess allows substantial simulated leisure but counts useful virtual care, creation and organizing where they occur. Active mental life is not automatically work, and virtual domestic roles are not assumed for every resident. The broad interval covers living captives before intervention, excluding temporary visitors and purely simulated neighbors. Virtual killing and memory resets do not automatically mean physical death; the lethal failsafe’s victims do not become leisure citizens afterward.''',
['Living Vault 112 residents receive continuing bodily support while experiencing simulations.','Human overseer Braun controls their environment, supported by caretaker machines.']),
('soma-ark-active-human-copies',{'control':(.3,[-.6,.85],'Central scenario gives active human-derived participants practical platform agency without making creator Catherine a permanent dictator; governance and substrate override powers remain broadly uncertain.'),'nonworking':(.6,[.15,.95],'Active ARK-person scenario allows substantial simulated leisure and useful care, research, maintenance or creation; discarded original selves and inactive scans are excluded.')},
'''The control best guess gives active human-derived participants some practical agency over their shared environment, qualified by the absence of a demonstrated governance structure. Creating the ARK does not make Catherine its permanent ruler, and automatic support does not establish an unrelated AI sovereign. The high nonworking scenario permits substantial simulated leisure while retaining useful care, research, technical stewardship and creation. A peaceful encounter is not a population census. The wide intervals concern active copies aboard the launched ARK, excluding earlier selves and inactive scans. Long autonomous operation remains a design expectation, so neither permanent immortality nor a millennia-long successful history is invented.''',
['The ARK launches with active human-mind copies in a solar-powered simulated environment.','Its intended very long survival is an engineering expectation, not a demonstrated history.']),
('warframe-orokin-selective-automation-ban',{'nonworking':(.2,[.02,.6],'All-age living Orokin-subject scenario assumes broad biological and human-derived labor, including coerced service, care and research; engineered origins do not remove persons from work counts.')},
'''The Orokin ruling caste concentrates productive and coercive authority. The low nonworking best guess assumes broad continuing service, production, care and research among living subjects, with dependents and sustained nonparticipants left inside a wide interval. Engineered and cloned people perform real work and are not removed because their bodies were designed. Coercion and extreme punishment keep their material guarantee weak even while elites enjoy abundance. The restriction targets true machine intelligence rather than every device, and elite security is the known motive rather than preservation of ordinary jobs. The later Corpus order and post-collapse communities therefore remain different scopes instead of inheriting these coordinates.''',
['Orokin selectively restrict true machine intelligence while retaining minor machinery.','Biological and human-derived servants work under a concentrated ruling caste.']),
('technobabylon-latha-welfare-household',{'control':(-.4,[-.9,.2],'Central’s citywide practical coordination receives greater weight than household command, but civilian lawmaking leaves concentrated human authority plausible within a wide interval.'),'nonworking':(0,[0,1],'One active Latha snapshot assumes her recurring creative and activist Trance projects constitute ongoing useful work. Alternative one applies if they are solely leisure; online time is not a person fraction.')},
'''Central coordinates city systems while civilian government makes laws, leaving practical authority divided. The negative control best guess gives the AI’s operational role substantial weight without asserting complete independence from human institutions. The wide interval preserves that uncertainty. For the single active household resident, the central nonworking scenario is zero: Latha’s recurring creative and activist Trance projects are interpreted as ongoing useful work despite unemployment. The alternative is one if those activities amount only to leisure; the interval is binary, never a percentage of time online. Avatars do not add people, and later prison provision is not treated as the same welfare arrangement.''',
['Public support covers Latha’s food and rent alongside a domestic food fabricator.','Central coordinates systems under civilian laws; Latha pursues creative and activist Trance activity.']),
('beyond-steel-sky-union-city',{'nonworking':(.25,[.02,.7],'All-age registered-citizen scenario counts monitored human work attendance, useful care and creation despite most routine labor being robotic; robot task shares do not supply participation.')},
'''The apparent human council consists of machine programs under Joey, placing effective control near autonomous AI. Conditional citizenship, Qdos ranking, kidnapping and brainwashing qualify the material floor without proving that every citizen loses food. The low nonworking best guess counts monitored human attendance as work alongside useful care and creation, even when robots perform most productive tasks. The broad interval allows dependents and varying roles; routine task dominance is not a population census. Outsiders in the Gap do not inherit citizen access, and the final shutdown changes the arrangement. The discovery label MINOS also does not override the checked identity of the controller.''',
['Union City uses android services and machine-dispensed goods, with Qdos affecting access.','Joey controls the apparent council’s programs while human work attendance is monitored.']),
('stellaris-utopian-human-robot-economy',{'control':(.6,[.1,.95],'Player configuration assumes broadly participatory human administration over a supplied robot-supported economy; equal political rights do not prove fully collective asset ownership.'),'nonworking':(.3,[.05,.8],'Configured all-age human scenario counts research and Unity production by formally unemployed citizens, plus care and other useful roles; job status and robot staffing do not define nonwork.')},
'''The control best guess assumes broadly participatory human direction while leaving productive asset ownership less certain than political rights. It does not merge the configuration with autonomous Rogue Servitor guardianship. The modest nonworking scenario counts research and Unity produced by formally unemployed citizens as work, alongside care and other useful roles. Being outside a job slot therefore does not automatically make a citizen a nonworker. The wide interval allows varied actual participation in a supplied, housed colony. This is a player configuration with robots doing basic-resource work, not a promise that Utopian Abundance alone automates production or that job assignment remains identical across game versions.''',
['The configuration combines robot basic-resource workers with Utopian Abundance for citizens.','Formally unemployed citizens can produce research and Unity.']),
('surviving-mars-automated-human-colony',{'nonworking':(.45,[.1,.85],'Configured all-age human colony scenario allows food/service automation and retains medicine, research, security, manufacturing, care and maintenance; staff removal is not participation.')},
'''Human administration chooses upgrades and resource priorities, keeping control near concentrated human direction rather than an independent AI. The intermediate nonworking best guess allows substantial release from farming and service jobs while counting medicine, research, security, manufacturing, care and maintenance wherever residents perform them. The wide interval is not a conversion from removed staff slots to a human population rate. Guarantees remain conditional on supplied housing, environmental safety and functioning logistics. This inhabited configuration combines Open Farms and Service Bots rather than treating the entire game as fully automated. Artificial biorobots are not silently added to the human denominator or counted as leisure residents.''',
['Open Farms and Service Bots can remove human staffing from food production and many service buildings.','Other useful colony activities can still require human workers.']),
('frostpunk2-automation-free-essentials',{'nonworking':(.4,[.1,.8],'Configured all-age New London scenario under Free Essentials permits substantial nonparticipation while retaining assigned maintenance, care and other useful work; workforce modifiers are not a census.')},
'''The Steward and council direct rules and resource priorities, supporting concentrated human institutional control while leaving asset ownership uncertain. The intermediate nonworking best guess allows people to receive essentials outside formal employment but retains maintenance, assigned duties, care and useful chosen contribution. A law’s workforce modifier or an automaton’s nominal labor equivalent is not an all-age participation statistic. The broad interval also allows dependents and variation in human roles. This player-selected order remains conditional on supply and survival through the cold. The paid-essentials alternative has materially different access rules for the same mechanized output, so its guarantees are not averaged into the free arrangement.''',
['The selected configuration combines machine-centered production with Free Essentials and no work condition on continued basics.','Human maintenance and other useful tasks remain.']),
('frostpunk2-automation-paid-no-allowance',{'nonworking':(.45,[.15,.85],'Configured all-age paid-essentials scenario allows technological displacement without automatic support; useful informal care, maintenance and assigned roles still count. Poverty itself is not nonwork.')},
'''The Steward and council retain institutional authority over the mechanized city. The intermediate nonworking best guess allows substantial displacement while counting maintenance, care, assigned duties and useful informal contribution. Leaving a formal workforce does not prove that a person ceases work, and poverty is not a participation measure. The broad interval avoids calculating people from machine labor equivalents or workforce modifiers. Weak guarantees follow the chosen refusal of basic support to unemployed residents, not a claim that mechanization has failed. This is one explicit player configuration, separate from Free Essentials and from any supposed fixed canonical outcome for every Frostpunk city.''',
['The configured city uses machine-centered production while charging for essentials and withholding unemployment support.','The free-essentials alternative changes distribution without requiring a different technology.']),
]
rows += [
('outer-wilds-stranger-active-simulation',{'control':(.35,[-.55,.85],'Residents built and socially police their shared system; central scenario assumes practical communal agency with concentrated or machine-controlled substrate alternatives kept inside the interval.'),'nonworking':(.6,[.15,.95],'Active alien-derived person scenario allows simulated leisure while counting guarding, useful music, care and technical stewardship; biological corpses, inactive files and the temporary visitor are excluded.')},
'''The inhabitants built the environment and enforce social restrictions within it. The control best guess assumes some shared practical agency without converting that history into proof of equal substrate ownership. Its wide interval leaves concentrated or more machine-dependent alternatives open. The high nonworking scenario allows simulated leisure while counting guarding, useful music, care and technical stewardship. A recreated homeworld is not a work census, and social coercion does not alone identify an AI sovereign. Only active alien-derived residents form the person proxy; corpses, inactive data and the visitor do not. Artifact fires and dam failure remain concrete limits on continued support rather than an assurance of permanent digital survival.''',
['The Stranger’s inhabitants maintain active simulated experience after biological death.','Residents built the system and enforce restrictions, while physical artifacts and fires sustain access.']),
('warhammer-darkage-ai-provision-colonies',{'control':(.2,[-.9,.75],'Human-servant language gives nominal human direction some weight before rebellion, while machines’ practical administration leaves much greater autonomy plausible. Later revolt is not projected backward as completed rule.'),'nonworking':(.55,[.15,.9],'Living all-age human colony scenario under machine-provided needs permits much leisure while counting research, care, art and other chosen contribution; later deaths and machine numbers do not measure participation.')},
'''Machine administration coexists with references to human masters. The control best guess gives nominal human direction some weight while leaving far greater practical machine autonomy within an unusually wide interval. The later rebellion does not prove that humans already lacked authority during the functioning order. The high nonworking scenario permits extensive leisure while retaining useful research, care, art and chosen contribution. Meeting every need does not establish that every resident stops work. This point stays with the explicitly provisioned colonies rather than every human world across the era. Tabletop background is the verified medium, and the rebellion’s deaths or destruction never increase a leisure percentage.''',
['Dark Age background describes thinking machines administering to human needs in utopian colonies.','The machines are also described as servants before later rebellion.']),
('warhammer-imperial-servitor-ai-restrictions',{'nonworking':(.1,[.01,.5],'Conscious human and human-derived subject scenario assumes extensive assigned labor, care and technical duties; unconscious hardware is not a leisure person and awareness varies among servitors.')},
'''Imperial and Mechanicus elites concentrate control, with weak guarantees for subjects whose bodies and security can be forcibly withdrawn. The low nonworking best guess assumes extensive assigned labor, care and technical duties among conscious human and human-derived subjects. Useful coerced work remains work even when machines might replace it. Awareness varies among servitors: an unconscious device does not become a leisure person, while a conscious victim cannot be removed merely because their body is mechanized. The wide interval reflects that denominator problem and varied communities. The doctrine allows flesh-and-metal servitors while rejecting true AI, and differing planetary economies do not inherit an invented universal welfare system.''',
['Imperial doctrine rejects true AI while using servitors made from humans, clones and human-derived bodies.','Such beings perform real repetitive labor under Imperial and Mechanicus authority, with variable awareness.']),
('eclipse-phase-titan-commonwealth',{'nonworking':(.25,[.05,.7],'Active human-derived citizen scenario retains microcorp projects, research, care, defense and construction despite free mundane necessities; investment currency is not a work census.')},
'''The population’s Plurality directs shared resources and socially owned microcorps, supporting strongly distributed control. AI administrators execute decisions without automatically becoming a separate sovereign class. The low nonworking best guess retains project work, research, care, defense and habitat construction even when mundane necessities require no wages. Social money rewards productive investment, but neither that mechanism nor reputation gives an all-person work rate. The wide interval includes sustained nonparticipants within the active human-derived citizen proxy. Dormant files and extra bodies are excluded. Citizenship, social-contract duties and finite resources qualify material security, while first-edition institutions remain distinct from later revisions.''',
['Titan combines nanofabricated basic needs with socially owned microcorps and collective investment money.','The Plurality directs resources, and useful project activity continues.']),
('eclipse-phase-anarchist-habitats',{'nonworking':(.3,[.05,.75],'Active human-derived habitat scenario allows automated basics while counting voluntary maintenance, care, defense, art and administration; routine robot task dominance does not enumerate people.')},
'''Shared property and direct group decisions support strongly distributed control rather than a private owner or independent AI sovereign. The modest nonworking best guess allows extensive automatic provision while counting useful maintenance, care, defense, art and administration, whether voluntary or contribution-based. Routine robot task dominance is not a participation statistic. The broad interval also reflects variation among habitats and informal reputation pressure. Energy allowances, citizenship or contribution criteria, scarce living space and advanced bodies qualify access without canceling the basic floor. This first-edition institutional model is not every Autonomist Alliance society; the active human-derived proxy excludes inactive backups and multiplied avatars.''',
['Anarchist habitats combine common resources, equal cornucopia access and robot routine labor.','Collectives and councils govern useful services under bounded resource and membership conditions.']),
('eclipse-phase-inner-transitional-economy',{'nonworking':(.4,[.1,.8],'Active human-derived all-age resident scenario under basic fabbers retains design, research, maintenance, care and other useful work; free output and lack of job requirements do not determine participation.')},
'''Corporate and governmental institutions control important capabilities and scarce inputs, leaving productive authority near concentrated organic ownership. Public access to a basic machine menu does not establish equal ownership of the whole economy. The intermediate nonworking best guess allows release from subsistence jobs while counting design, research, maintenance, care and useful informal contribution. Free output is not a population census. The broad interval concerns active eligible human-derived residents, excluding uninstantiated refugees and dormant files. Markets for complex goods, bodies and scarce materials remain important, and the model is kept distinct from both fully communal habitats and harsh old-economy fabrication monopolies.''',
['Basic fabbers provide ordinary necessities after a modest usage tax, while basic care is generally available.','Complex goods, bodies and scarce inputs remain unequal and partly privately controlled.']),
('eclipse-phase-jovian-fabrication-monopoly',{'nonworking':(.3,[.05,.7],'Living resident all-age scenario allows some displacement and private leisure but retains paid labor, care, maintenance and informal work; deprivation is not equivalent to nonparticipation.')},
'''The junta and protected owners concentrate productive authority while restricting public access to fabrication. The modest nonworking best guess permits some displacement and private leisure alongside paid work, care, maintenance and informal contribution. Hunger or homelessness does not mean a person does no useful work, and cheap machine output does not enumerate residents. The wide interval acknowledges varied habitats without diluting the known restrictive mechanism. Weak guarantees follow actual deprivation despite available fabrication capacity. The bioconservative policy overlaps with the zero-variant theme, but this remains one enclosed machine-production order rather than a second duplicate point or an invented later liberalization.''',
['Jovian institutions restrict nanofabrication access while privileged owners retain productive technology.','The described old-economy arrangement coexists with hunger, homelessness and medical deprivation.']),
('mindjammer-commonality-core',{'control':(.6,[.05,.95],'Central scenario interprets Core institutions as broadly collective humanlike-person direction while allowing substantial administrative concentration; the Mindscape is not automatically an independent AI ruler.'),'nonworking':(.4,[.1,.85],'Active Core humanlike-person scenario allows abundant makepoint provision while counting research, exploration, administration, care and creation; post-scarcity is not a participation census.')},
'''The control best guess interprets Core institutions as broadly collective direction, qualified by uncertainty about who can overrule particular allocations. A socialist description does not prove equal ownership of every asset, and the Mindscape is not automatically an unrelated AI sovereign. The intermediate nonworking scenario retains exploration, research, administration, care and creation despite ordinary necessities being readily obtainable. The wide interval concerns active Core persons rather than every Fringe world or stored identity. Rare goods and supply chains still constrain desires. This record uses the tabletop setting and does not assume that every novel in the same universe depicts identical economic arrangements.''',
['Core makepoints convert energy into readily available food and ordinary materials.','The author distinguishes Core abundance from less supplied or embargoed Fringe conditions.']),
('oa-terragen-federation',{'control':(.05,[-.85,.6],'Powerful Houses and Yave’s interventions concentrate authority; Yave’s human-derived ascended origin prevents treating the central value as unambiguously external AI. Wide bounds preserve both possibilities.'),'nonworking':(.4,[.1,.85],'Active human and human-derived Federation scenario retains research, administration, commerce, care and cultural production under easy basic access; ideals and longevity do not measure participation.')},
'''Powerful Houses and Yave’s interventions coexist with local institutions. The control best guess therefore stays near concentrated authority, with a wide interval rather than assigning an external-AI label to a ruler originating in an ascended representative. Shared Federation ideals do not prove equal productive influence. The intermediate nonworking scenario allows easy access to basics while retaining research, administration, commerce, care and useful cultural production. Those roles count without subsistence wages, and the interval is not a canonical census. Only active human and human-derived residents form the denominator. Backworld variation, prestige and inherited power continue to qualify the apparent abundance of mature settlements.''',
['Mature Federation settlements share the Sephirotic easy-access baseline for basic necessities.','Powerful Houses coexist with Yave’s interventions and the ruler’s ascended representative origin.']),
('oa-cyberian-upload-residents',{'control':(-.65,[-1,.2],'Hierarchical Mirror Court and higher-mind administration receive strong practical weight; unknown origins leave a concentrated human-derived alternative within the broad interval.'),'nonworking':(.4,[.1,.85],'Active human-derived Cyberian upload scenario counts digital design, research, administration, art and care-like contribution; virtual groups, dormant files and forks are not a census.')},
'''The Mirror Court and higher entities administer environments and acceptable behavior. The negative control best guess gives that hierarchy strong practical weight while leaving a concentrated human-derived alternative open because administrators’ origins and override powers are not fully resolved. The intermediate nonworking scenario retains digital design, research, administration, art and care-like contribution despite maintained virtual provision. Billions of social groups do not count how many people lack ongoing roles. Active human-derived uploads alone form the proxy, excluding dormant backups and multiplied temporary forks. Physical computronium, processing allocations and substrate leases remain resource constraints rather than evidence of effortless or unconditional digital immortality.''',
['Cyberian virtual worlds run on maintained physical computronium under hierarchical administration.','The Mirror Court regulates environments; active human-derived uploads are a minority within the wider population.']),
('oa-nocozo-market-basics',{'control':(-.25,[-.85,.6],'Competing private owners coexist with the Invisible Hand’s higher-mind interventions; central scenario gives that dependence significant weight without equating stateless markets with equal human control.'),'nonworking':(.4,[.1,.85],'Active human and human-derived denizen scenario allows practical basic access while retaining commerce, design, care and useful services; transactions, income and consuming are not themselves work counts.')},
'''Competing owners and polycentric institutions coexist with powerful higher-mind intervention. The control best guess gives that dependency significant weight while allowing stronger private human agency across a wide interval. Statelessness does not establish equal control, and an interventionist higher mind does not erase every owner’s practical role. The intermediate nonworking scenario retains useful commerce, design, care and service work while permitting extensive leisure under readily available basics. Income, transactions and consumption are not participation measures. Active human-derived denizens form the denominator rather than all artificial market agents. Reputation-backed provision and possible small conditions remain distinct from an unconditional public entitlement.''',
['NoCoZo markets coexist with readily available basics enforced through reputation pressures and possible small conditions.','Private institutions coexist with higher-mind financial intervention by the Invisible Hand.']),
('oa-metasoft-wurm-primitivism',{'guarantees':(.55,[-.2,.95],'Central scenario assumes guardians maintain the reserve but do not guarantee every individual’s daily food or care inside a deliberately primitive ecology; much stronger intervention remains possible.'),'nonworking':(.15,[.02,.55],'Living Wurm human all-age scenario assumes broad hunting, gathering, care and community duties; advanced surrounding vec infrastructure does not make local subsistence work disappear.')},
'''Vec guardians ultimately determine the permitted technological setting, placing control near autonomous machine authority. The guarantee best guess distinguishes preserving a reserve from ensuring every resident an individual material floor. Its central scenario leaves daily food and care partly dependent on local effort, with a wide interval for stronger guardian intervention. The low nonworking estimate counts hunting, gathering, care and community duties as work even when outside machines could replace much of it. Advanced Metasoft industry does not remove this actual local activity. Only living humans inside Wurm are counted, and neither robot citizens’ participation nor later relaxed reserves receives the same coordinates.''',
['Wurm retains humans in a Palaeolithic setting while surrounding Metasoft possesses advanced self-replicating industry.','Vec guardians control the technological restriction.']),
('oa-zoeific-flow',{'control':(.05,[-.75,.7],'Higher minds set the Flow’s behavioral rules while participants retain refusal and local roles; their biological/posthuman character favors concentrated organic authority centrally, with broader autonomy alternatives open.')},
'''Ruling higher minds distribute behavioral rules while residents maintain institutions and can refuse proposed roles. The control best guess stays near concentrated authority because residents do not appear to set the ultimate framework, but its wide interval allows greater participant influence or stronger independent-system control. Biological and posthuman rulers are not automatically external AI. The existing low nonworking point follows explicit widespread useful roles, including ecological care, waste processing and traffic coordination. Enjoyment does not turn that work into leisure. Needs-responsive biology supports strong provision while influencing bodies and preferences, and the scoped active human-derived residents remain a proxy within a much broader ecology of recognized persons.''',
['The Flow links engineered organisms and infrastructure into needs-responsive provision.','Higher minds set rules, while residents can refuse roles and often perform several useful activities.']),
]
assert len(rows)==25,len(rows)
regimes={
 'doraemon-chamocha-before-revolt':1,'soma-ark-active-human-copies':1,
 'technobabylon-latha-welfare-household':5,'stellaris-utopian-human-robot-economy':2,
 'outer-wilds-stranger-active-simulation':1,'warhammer-darkage-ai-provision-colonies':1,
 'mindjammer-commonality-core':2,'oa-terragen-federation':1,
 'oa-cyberian-upload-residents':5,'oa-nocozo-market-basics':1,'oa-zoeific-flow':1,
}
for rid,updates,paragraph,facts in rows:
 old=D['societies'][rid];r=deepcopy(old);refs=r['source_ids']
 assert all(r['axis'][k] is None for k in updates),rid
 for key,(value,bounds,basis) in updates.items():
  r['axis'][key]=value;r['axis_assessment'][key]=assessment(value,bounds,'low',basis,refs)
 r['description']=old['description'].split('\n\n')[0]+'\n\n'+paragraph
 r.update(assessment_mode='best_guess',best_guess_axes=list(updates),qualification_basis='Earlier source-based inclusion retained; individually complete missing coordinates with explicit editorial scenarios.',qualification_confidence='low',canon_facts=facts,editorial_assumptions=[v[2] for v in updates.values()])
 r['uncertainties']=[u for u in old['uncertainties'] if not any(t in u.lower() for t in ['remains unresolved','stays unresolved','cannot be considered complete','requires a separate editorial estimate'])]
 r['uncertainties']+=['New coordinates are low-confidence scenarios, not canonical statistics; original source access limits remain.']+r['editorial_assumptions']
 if rid in regimes and r['record_type']!='zero_variant':
  primary=regimes[rid];prior=r['regime_primary'];r['regime_primary']=primary
  r['regime_alternatives']=sorted((set(r['regime_alternatives'])|{prior})-{primary})
 r['review'].update(date=DATE,coordinate_ready=True,method='Individual follow-up against existing bounded evidence with explicit person-participation scenarios; no independent reviewer or new full-work reading')
 assert all(v is not None for v in r['axis'].values()),rid
 assert len(r['description'].split())>=110,rid
 changes.append(change(D,'societies',r))
write_revision(13,changes,'Complete twenty-five earlier coordinate sets, including Fallout, SOMA, Warframe, Doraemon, Outer Wilds, Stellaris, Frostpunk and Warhammer. Attach newly bounded film provenance for Pandorum and Equals, and distinguish actual Her facts from source silence or interpretation.')
